# Preserved original worked-example chapters; loaded as AST data by build.py.
add('BBS · Project to client invoices', '<p class="lead">An illustrated, step-by-step guide to J&amp;A Automation.</p><p>Owner, Finance, crew chief and workers · 5 October 2026.</p><p>The independent training project is <strong>BBS · Ejemplo de manual</strong>, project <strong>C-0050-P-20261005</strong>. It has three fictional team members. Original BBS and Junkers projects are outside this exercise.</p>' + table(['Stage', 'Source records', 'Invoice drafts'], [['1 · 1–4 October', '35 actual hours and four approved expenses', 'USD 2230 labor + USD 182 expenses'], ['2 · 5–11 October', '7.5 actual hours, with hourly/daily/weekly charges', 'USD 2260 labor']]) + note('These are training examples. No invoice has been issued or emailed and no real payment has been recorded. Screenshots are from the live application; saved example names and descriptions retain their original record text.'), '01-project-team.png', 'The independent training project with its three assigned people.')

add('1 · Understand the complete workflow', table(['Item', 'Meaning'], [['Issuer', 'J&A, the company selling services and issuing the invoice.'], ['Client', 'The customer receiving the invoice and paying J&A.'], ['Customer rate', 'What J&A charges for a person’s hour, worked day or worked week.'], ['Worker pay', 'Separate compensation for that person.'], ['Internal cost', 'The direct labor cost used in the project contribution calculation.'], ['Expense', 'A source purchase with independent payer, reimbursement and client recovery rules.']]) + steps('Sign in as the owner and open <strong>Projects</strong>. Set up the client, project, assignments and dated commercial terms.', 'Workers or a delegated crew chief record time and expenses, then submit them.', 'An authorized reviewer approves the operational records. Finance reviews billability and expense classification.', 'Configure billing streams and prepare invoice drafts. Review their source records, quantities, totals and PDF.', 'For a real client invoice, approve, issue, download the final PDF, send it and separately record actual collection.') + note('Invoice cadence is independent of the rate unit. For example, a monthly invoice can charge USD 600 for each worked day.'))

add('2 · Create a client and project', steps('In <strong>Projects</strong>, create the client if it does not exist. Enter its legal name, display name, currency, timezone, billing contact/email, billing address, payment terms and PO reference.', 'Choose <strong>Create project</strong>. Select the client and enter the project name, cost center, currency, timezone and start date.', 'This example uses <strong>Time &amp; Materials (tm)</strong>, USD, America/New_York, a 1 October start and PO BBS-DEMO-20261005.', 'Review the optional assignment table. Add people and configure their terms during creation, or add them later in <strong>Team</strong>.', 'Save once and reopen the project. Check the assigned team and client details.') + note('Reference/planned hours never fabricate actual time entries. Hour-based hybrid included-minute billing requires hourly customer rates; use T&amp;M for full day/week charges.'), '17-create-project-form.png', 'The real creation form, including optional per-person assignments; this screenshot does not save another project.')

add('3 · Project defaults and person overrides', steps('Open <strong>Project → Billing → Configure project defaults</strong>. Set customer rate, internal cost, compensation and expense defaults for new assignments.', 'The initial example defaults are USD 60/h customer revenue, USD 35/h internal cost, USD 30/h worker pay and worker-paid expenses reimbursed/recovered at cost.', 'Open <strong>Configure this project’s invoices</strong> and continue to <strong>3. Review each person</strong>. This step is in project billing setup, not inside an invoice.', 'Set an effective date and edit each person. Click <strong>Save person terms</strong>; changing a visible field alone does not save it.', 'If matching default rates should become explicit independent agreements, select <strong>Save these rates as explicit person overrides</strong>.') + note('Changing project settings/defaults does not erase saved person overrides. “Use project defaults in this draft” fills a person’s draft; review its effective date and save to apply it. Same-date agreements are immutable: use a later effective date for a new revision.'))

add('4 · J&A issuer and invoice details', steps('In <strong>2. Billing details</strong>, J&amp;A Automation is selected by default for the matching project currency. Review it when setting up new or existing projects.', 'Check billing contact, recipient and payment terms. Selecting a project in <strong>New billing stream</strong> fills available project/client currency, PO, contact, email and terms.', 'Select Standard, Detailed or Summary layout, and grouping by worker, day, category, detail or summary. These options affect presentation, not approved source money.', 'Choose applicable labor and expense tax profiles if configured. The example has no tax profile; do not invent tax settings to copy it.', 'Automatically preparing drafts is optional. It is disabled in the training project. Invoices are never automatically issued or sent by this setup.') + note('A valid issuer in the app has configured identity, address, currency, effective legal revision and project authority. The app’s validation is not a government verification of the company’s tax registration.'), '18-ja-default-issuer.png', 'Actual issuer, cadence, tax, layout, contact and payment-term controls.')

add('5 · Crew chief: hourly billing and hourly pay', steps('Find the crew chief in <strong>Review each person</strong>.', 'Select <strong>Customer billing unit: Hourly</strong>, customer rate USD 80/h and internal cost USD 45/h.', 'Set the separate worker compensation method to <strong>Hourly</strong>, USD 40/h. The USD 80 customer charge is not the worker’s pay.', 'For worker-paid expenses use at-cost reimbursement and client recovery with 10% markup.', 'Save and reload. In stage 1, ten actual hours produce USD 800 customer labor and USD 400 expected compensation. No compensation payment is recorded.'), '19-chief-hourly.png', 'Separate customer charge, hourly worker pay and expense markup.')

add('6 · Technician 1: full daily customer charge', steps('Set the new agreement effective from <strong>5 October 2026</strong>. Earlier work remains at its initial USD 60/h customer rate.', 'Choose <strong>Customer billing unit: Daily</strong> and customer daily rate USD 600.', 'Keep worker pay <strong>Daily</strong>, USD 240/day, with internal cost USD 35/h. Customer daily charge and worker daily pay are separate fields.', 'Keep worker-paid expenses, project-default reimbursement and client recovery at cost.', 'Click <strong>Save person terms</strong> and reload. Two approved billable parts of 1.5 h and 0.5 h on one day charge one full day: USD 600.') + note('A partially worked day charges the full customer daily rate once per person/project/day. Actual time remains 2 h. The new agreement does not reprice the approved 2–3 October records.'), '20-worker-daily.png', 'USD 600 daily customer charge and USD 240 daily worker compensation.')

add('7 · Technician 2: weekly charge, fixed-period pay', steps('Starting <strong>5 October 2026</strong>, select <strong>Customer billing unit: Weekly</strong>, USD 1500/week.', 'Keep worker compensation <strong>Fixed per billing period</strong>, USD 900, and internal cost USD 30/h. The compensation period is not automatically the customer weekly charge unit.', 'Use <strong>Company card</strong> for expenses, no worker reimbursement and expenses included in labor price.', 'Save and reload. Check USD 1500/week and confirm the compensation and expense choices were preserved.', 'The customer week is Monday–Sunday. Two approved billable parts of 2 h and 1.5 h in the same week charge USD 1500 once.') + note('A partially worked week charges the full weekly customer rate. Additional parts do not charge another week, including attempts to invoice them in another period. Actual recorded hours remain unchanged.'), '21-worker-weekly.png', 'Weekly customer billing, fixed compensation per billing period and company-paid expenses.')

add('8 · More compensation and expense options', table(['Compensation method', 'How to use it'], [['Hourly', 'Rate for eligible actual hours.'], ['Daily', 'Daily compensation under its applicable rules.'], ['Fixed per billing period', 'One configured amount for the applicable settlement period.'], ['Fixed project amount', 'A project-level fixed agreement; review its settlement.'], ['Percentage of eligible client labor', 'Configured percentage and eligible labor basis; not a percentage of every expense or tax.']]) + table(['Expense choice', 'Effect'], [['Worker', 'Can reimburse at cost or not reimburse.'], ['Company card / Company direct', 'Company pays; do not reimburse the worker.'], ['Client / Third party', 'Identify the actual payer and review the applicable policy.'], ['At cost / Cost plus markup', 'Recover the source cost or source cost plus markup from the client.'], ['Included / Do not charge / Client pays directly', 'No additional labor-inclusive charge, nonbillable recovery or direct client payment.']]) + note('Payer, worker reimbursement and customer recovery are independent. Changing the selected payer preserves policies for other payers. The same worker can have different dated terms in different projects.'))

add('9 · Assign the crew and chief', steps('In <strong>Team</strong>, assign the three people with valid membership dates. The example accounts have the worker role.', 'Configure the chief’s crew delegation and its effective dates. Assignment and delegation are separate permissions.', 'As the chief, open <strong>Crew</strong>, select the project/date and the delegated workers.', 'Use shared mode for common hours or individual mode for different hours. Choose category, description and whether to submit.', 'The chief records personal hours in <strong>Time</strong>. Crew delegation does not grant owner access or all commercial data.'), '06-chief-crew-hours-shared-receipt.png', 'Actual crew recording and shared receipt links.')

add('10 · Record and submit time', steps('In <strong>Time</strong>, a worker selects an assigned project, work date, category, duration and activity description.', 'Use the category describing the work: regular time, travel, commissioning, overtime or another available category. Commercial rules determine treatment.', 'Save the draft and submit it. A time draft alone is not invoice-ready.', 'Review the time calendar or weekly sheet. To fix an existing record, use its permitted edit/correction path instead of making a duplicate.', 'For 3 October, the chief enters 3 h travel for technician 1 and 6 h travel for technician 2 in individual crew mode.') + note('Recorded, approved, billable and billed are different states/concepts. An hourly commercial daily minimum does not create additional actual hours.'), '07-chief-individual-crew-hours.png', 'Different actual travel hours for each crew member.')

add('11 · Stage 1: 35 approved actual hours', table(['Person', '2 October', '3 October', 'Actual total', 'Initial customer revenue'], [['Chief', '8 h commissioning', '2 h overtime', '10 h', 'USD 800'], ['Technician 1', '8 h regular', '3 h travel', '11 h', 'USD 660'], ['Technician 2', '8 h regular', '6 h travel', '14 h', 'USD 770'], ['Total', '24 h', '11 h', '35 h', 'USD 2230']]) + steps('The chief/workers submit these six parts.', 'An authorized reviewer approves them in <strong>Approvals</strong>.', 'Finance records its review and marks eligible time billable.', 'Open <strong>Finance → Economic Review → Time entries</strong> for the project and compare the six stage-1 rows with this table.') + note('All 35 stage-1 hours are approved and Finance-reviewed. Their customer rates are 80, 60 and 55 per hour. Expected stage-1 compensation is USD 1780 (400 + 480 + 900), with no payment recorded.'), '25-finance-hours.png', 'The first six rows are stage 1 (35 h); the last two visible rows belong to stage 2.')

add('12 · Record expenses and a shared receipt', steps('In <strong>Expenses</strong>, choose project, worker, date, category, vendor, currency, amount and payer.', 'Enter the business reason and attach a receipt where required. Save and submit.', 'Record the fictional hotel at USD 100, paid by the worker. Record tools at USD 50, paid by company card.', 'Within the delegation, the chief records a single USD 60 crew meal receipt and allocates USD 30 to each technician’s time record.', 'The allocation links one expense to two parts. Do not add two extra USD 30 expenses; there remains one USD 60 financial source.'), '10-worker-expenses.png', 'The worker’s actual expense view for hotel and shared meal.')

add('13 · Four approved, Finance-reviewed expenses', table(['Expense', 'Payer', 'Spent', 'Worker reimbursement', 'Client charge'], [['Chief parking', 'Worker', '20', '20', '22'], ['Technician 1 hotel', 'Worker', '100', '100', '100'], ['Shared meal', 'Worker', '60', '60', '60'], ['Technician 2 tools', 'Company card', '50', '0', '0'], ['Total USD', '', '230', '180', '182']]) + steps('Approve the operational expense first.', 'In <strong>Finance</strong>, review/classify its commercial treatment: at cost, plus markup or included. Check the person, date, payer and category policy.', 'Record Finance review. All four example expenses are approved, classified and reviewed.', 'The client expense invoice has three additional charges: 22 + 100 + 60 = USD 182. Tools are included, so they add no expense charge.') + note('USD 230 spent, USD 180 reimbursable and USD 182 customer recovery are different totals. A shared receipt allocation does not duplicate an expense or create two customer charges.'), '26-finance-expenses.png', 'Actual source expense economics and the separate client recovery amounts.')

add('14 · Worker and chief views', steps('Workers review their own time, expenses and <strong>My Pay</strong> within their account permissions.', 'For stage 1, technician 1 has 11 h and USD 480 expected daily compensation for two days; reimbursable hotel/meal expenses are USD 160.', 'Technician 2 has 14 h and the configured USD 900 fixed compensation for the displayed period. It is not multiplied for each source part.', 'The chief also has Crew access for delegated people. Owner/Finance configures commercial rates and prepares invoices.', 'My Pay values are projections or compensation states; they do not prove a bank transfer.') + note('Worker views do not disclose customer commercial rates or internal cost. The training agreements shown in this manual are fictional.'), '11-worker-fixed-period-pay.png', 'Actual worker view for stage-1 fixed-period compensation.')

add('15 · Separate labor and expense billing streams', steps('At project billing setup step 1, choose <strong>One invoice with two sections</strong> or <strong>Two separate invoices</strong>.', 'A combined stream includes approved labor and client-chargeable expenses. Separate streams allow different cadence and tax profiles.', 'The example uses monthly expenses and weekly labor. Its first partial labor period is manual, 1–4 October; the following weekly stream starts Monday 5 October.', 'In <strong>Billing → New billing stream</strong>, select the project, review autofilled fields and choose what cannot be inferred: stream, cadence, dates/anchor, layout, grouping and automation.', 'Save the dated configuration. Review existing streams before creating another one.') + table(['Cadence', 'Review'], [['Weekly', 'Monday–Sunday boundaries and effective start.'], ['Every 14 days', 'Anchor date and two-week cycle.'], ['Semi-monthly', 'Two calendar periods per month.'], ['Monthly', 'Source month and issuer coverage.'], ['Manual', 'Explicit dates, useful for the initial partial period.']]) + note('Invoice frequency does not change the customer rate unit. Revising a stream preserves history. Combining/separating does not permit duplicate source billing.'))

add('16 · Create the 35-hour client invoice', steps('Open <strong>Billing → Create invoice draft</strong>.', 'Select the training project and its initial <strong>Labor · Manual</strong> stream.', 'Use period <strong>1–4 October 2026</strong>. Review readiness: effective rates, approved/billable sources and availability.', 'Prepare and open the draft in Preview. Check six sources, 35 actual hours and subtotal <strong>USD 2230</strong>.', 'Verify the client, J&amp;A issuer, PO, currency, descriptions, grouping and total. Click <strong>Download PDF · Preview</strong>.') + note('The invoice period is the service/expense date range. It is different from issue date and due date. A draft PDF is a preview; it does not assign a final invoice number or send anything.'), '22-labor-lines.png', 'Actual stage-1 labor invoice table. Bank details are outside the screenshot.')

add('17 · Create the client expense invoice', steps('Choose the same project’s <strong>Expense · Monthly</strong> stream. This is the invoice to send to the client for recoverable expenses.', 'Use <strong>1–31 October 2026</strong> and prepare the draft.', 'Review three charges: parking USD 22, hotel USD 100 and shared meal USD 60. Subtotal: <strong>USD 182</strong>.', 'The USD 50 tools expense is included in labor and adds no expense invoice charge. The meal appears once.', 'Download its preview PDF. To actually send it, follow approval → issuance → final PDF → sending, as described in chapter 21.') + note('USD 180 worker reimbursement is not the USD 182 client invoice. Issuer coverage must span the selected monthly period even when expenses occurred only on two days. This monthly draft does not prevent saving later person agreements.'), '23-expense-lines.png', 'The separate client expense invoice has three charges from four operational expenses.')

add('18 · One invoice with hourly, daily and weekly units', table(['Person', '5 October parts', 'Billable unit', 'Customer USD'], [['Chief', '1.5 h + 0.5 h', '2 h × 80', '160'], ['Technician 1', '1.5 h + 0.5 h', '1 day × 600', '600'], ['Technician 2', '2 h + 1.5 h', '1 week × 1500', '1500'], ['Total', '7.5 actual hours', 'Different unit types', '2260']]) + steps('Record/submit the six stage-2 parts for 5 October. Obtain operational approval and Finance review.', 'Choose <strong>Labor · Weekly</strong>, period <strong>5–11 October 2026</strong>.', 'Prepare the draft and verify <strong>USD 2260</strong>. Additional same-day/week parts are marked as already covered and add no further charge.', 'The PDF keeps hours, days and weeks separate and preserves 7.5 h actual recorded time.', 'Download the PDF. The project now has 42.5 h accumulated: 35 h stage 1 + 7.5 h stage 2.') + note('The earlier USD 2230 invoice is unchanged. Do not bill reserved sources again. If there are no new full-unit charges, the app reports it instead of creating another duplicate invoice.'), '24-mixed-lines.png', 'Actual mixed-unit invoice with zero additional charge for covered day/week parts.')

add('19 · Issuer coverage and legal revisions', steps('Open <strong>Finance → Project issuing authority</strong>. Review J&amp;A’s legal revision and the project assignment dates.', 'A legal revision preserves the company identity and address effective at that time. Later revisions retain earlier history.', 'Consecutive assignments of the <strong>same revision</strong> may cover one continuous period: for example 28–30 September followed by 1 October onward.', 'If coverage has a real missing day, PDF generation stays blocked. The message identifies issuer, project, invoice period and missing dates, with the place to review the setup.', 'If a period crosses different issuer legal revisions, review or split the period. The app does not silently combine legal identities.') + note('J&A’s default selection does not bypass currency or effective-date checks. Issued invoices retain their historical issuer even when future defaults, addresses or contact settings change.'))

add('20 · Edit a draft and download its PDF', steps('Open the invoice preview. Editable invoice presentation fields are separate from approved source records.', 'Review the available customization fields, such as PO, texts, terms and presentation. Save, reload and check the result.', 'Rates and source money come from commercial rules and approved records. Use the correct dated agreement or source correction to change the financial basis.', 'Click <strong>Download PDF · Preview</strong>. Confirm period, units and total in the downloaded document.', 'When a rule/source changes while an invoice is a draft, use its available refresh/review actions and compare totals again.') + note('All three example native invoice PDFs have been generated successfully. Public manual images show their tables/download controls and omit J&A’s real bank footer. Authorized native invoice PDFs retain their payment instructions.'), '27-pdf-download.png', 'The actual draft PDF download control, with issuer coverage resolved.')

add('21 · Approve, issue and send to the client', steps('When the draft is correct, the authorized role approves it. Approval is separate from issuance, sending and collection.', 'Before issuing, configure an accountant-approved numbering policy for J&amp;A and review all issuer, tax, date, source and readiness requirements. The example reports the missing approved policy and stays a draft.', 'Issue a real invoice only after those requirements are satisfied. Issuance creates the historical financial document and final number. Wait until its final PDF is ready.', 'Review the recipient/contact and use the available invoice sending action, or download the final PDF for your approved delivery process. Labor, expenses and combined invoices use this same lifecycle.', 'Sending is not payment. Record an actual collection only after receipt; review unpaid, partially paid and paid balances.', 'Correct an issued document through the available void/credit/adjustment/replacement lifecycle, preserving audit history.') + note('This chapter explains the remaining real-client steps. Issuance, client emails and payments were deliberately not performed with the fictional training data.'))

add('22 · Final checks and troubleshooting', table(['Problem', 'Check'], [['Cannot find Review each person', 'Project → Billing → step 3; assigned people and owner/Finance permission.'], ['Sources missing', 'Project, period, submission, operational approval, Finance review and expense classification.'], ['Already billed / no new charges', 'Reserved sources and previously charged day/week; do not duplicate records.'], ['Cannot save terms', 'Effective date, active membership and overlapping approved invoices/finalized settlements.'], ['PDF blocked', 'Issuer legal revision, currency and missing coverage dates in the message.'], ['Cannot issue', 'Approved numbering policy and all readiness requirements.'], ['Incomplete forecast', 'Planned hours alone cannot determine full customer days/weeks.']]) + note('Completed example: three people, 42.5 actual hours, four expenses and three invoice drafts: USD 2230 labor, USD 182 expenses and USD 2260 mixed-unit labor. All 35 stage-1 hours and four expenses remain approved and Finance-reviewed. No invoice was issued/sent and no payment was recorded.'))
